changeSet.sql:
ALTER TABLE notices
    ADD COLUMN preference_policy VARCHAR(20) NOT NULL DEFAULT 'CONFIGURABLE',
    ADD CONSTRAINT ck_notices_preference_policy CHECK (preference_policy IN ('CONFIGURABLE', 'REQUIRED'));

UPDATE notices notice
   SET preference_policy = outbox.preference_policy
  FROM notification_outbox outbox
 WHERE outbox.event_key = notice.source_event_key
   AND outbox.preference_policy = 'REQUIRED';

CREATE INDEX idx_notification_push_delivery_admin
    ON notification_push_delivery(status, scheduled_at, id) WHERE deleted = FALSE;
